@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Newsreader:opsz,wght@6..72,500;6..72,600&display=swap');

:root{font-family:'DM Sans',sans-serif;color:#1d211d;background:#f5f5f1;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,textarea,select{font:inherit}button{color:inherit}.app{min-height:100vh;display:grid;grid-template-columns:254px 1fr}.sidebar{position:fixed;width:254px;height:100vh;background:#1c241e;color:#f4f3eb;padding:30px 20px 22px;display:flex;flex-direction:column;z-index:20}.brand{display:flex;align-items:center;gap:11px;font-family:'Newsreader',serif;font-size:25px;font-weight:600;letter-spacing:-.6px;padding:0 8px 35px}.brand-mark{width:31px;height:31px;border-radius:9px;background:#dcefc6;color:#1c241e;display:grid;place-items:center}.nav-main{padding-bottom:23px;border-bottom:1px solid #354039}.nav-item{width:100%;border:0;background:transparent;color:#b8c0ba;padding:10px 11px;border-radius:9px;display:grid;grid-template-columns:21px 1fr auto;align-items:center;text-align:left;gap:10px;font-size:13.5px;cursor:pointer;margin:2px 0}.nav-item:hover{background:#27312a;color:#fff}.nav-item.active{background:#f0f2eb;color:#1a231c;font-weight:600}.nav-item em{font-style:normal;font-size:11px;opacity:.65}.nav-icon{display:flex}.nav-section{padding-top:25px}.section-label{padding:0 9px 9px 11px;color:#7e8981;display:flex;align-items:center;justify-content:space-between;font-size:10px;font-weight:600;letter-spacing:1.4px}.section-label button{background:none;border:0;color:#929d95;padding:3px;cursor:pointer}.sidebar-bottom{margin-top:auto}.upgrade-card{border:1px solid #3c493f;border-radius:13px;padding:15px;margin:0 2px 15px;background:linear-gradient(145deg,#263129,#202923)}.spark{color:#dcefc6;margin-bottom:15px}.upgrade-card strong{font-family:'Newsreader',serif;font-size:16px;font-weight:600}.upgrade-card p{color:#99a39b;font-size:11.5px;line-height:1.5;margin:6px 0 0}.profile{width:100%;border:0;border-top:1px solid #354039;background:none;color:#fff;padding:17px 4px 0;display:flex;align-items:center;gap:10px;text-align:left;cursor:pointer}.profile>span:nth-child(2){flex:1;display:flex;flex-direction:column}.profile strong{font-size:12px;font-weight:500}.profile small{color:#8b958d;font-size:10.5px;margin-top:2px}.avatar{background:#c1d7e1;color:#26352d;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;font-weight:600;font-size:10px}.mobile-close{display:none}main{grid-column:2;min-width:0}.topbar{height:78px;border-bottom:1px solid #dedfd8;background:rgba(248,248,244,.85);backdrop-filter:blur(12px);padding:0 4.7vw;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:10}.search{display:flex;align-items:center;gap:11px;color:#858982;width:min(420px,45vw)}.search input{background:transparent;border:0;outline:none;width:100%;font-size:13px}.search input::placeholder{color:#989c95}.search kbd{border:1px solid #d5d6d0;border-radius:5px;padding:3px 6px;color:#969a93;font-size:10px;white-space:nowrap;background:#fff}.add-button,.empty button{border:0;background:#202920;color:#fff;padding:10px 16px;border-radius:8px;font-size:12px;font-weight:600;display:flex;gap:8px;align-items:center;cursor:pointer;box-shadow:0 2px 3px #17221920}.add-button:hover,.empty button:hover{background:#324435}.menu-button{display:none;border:0;background:none}.content{padding:55px 4.7vw 70px}.hero{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:34px}.eyebrow{font-size:10px;letter-spacing:1.6px;font-weight:600;color:#879087;margin:0 0 13px}.hero h1{font-family:'Newsreader',serif;font-weight:500;font-size:43px;line-height:1;margin:0;letter-spacing:-1.5px}.hero h1 sup{font-family:'DM Sans',sans-serif;font-size:11px;color:#8c918a;vertical-align:top;margin-left:9px;letter-spacing:0}.subtitle{margin:12px 0 0;color:#7b7f79;font-size:13px}.toolbar{display:flex;gap:9px}.view-toggle{display:flex;border:1px solid #d8dad3;border-radius:8px;background:#eeeFea;padding:3px}.view-toggle button{border:0;background:transparent;color:#979b95;width:32px;height:28px;border-radius:5px;display:grid;place-items:center;cursor:pointer}.view-toggle button.active{background:white;color:#242b25;box-shadow:0 1px 3px #1f291f17}.sort{border:1px solid #d8dad3;background:#fafaf7;border-radius:8px;padding:0 12px;display:flex;align-items:center;gap:7px;font-size:11px;cursor:pointer}.bookmarks.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:19px}.bookmark-card{border:1px solid #ddded7;border-radius:13px;background:#fafaf7;overflow:visible;min-width:0;transition:.2s;position:relative}.bookmark-card:hover{transform:translateY(-3px);box-shadow:0 12px 30px rgba(40,49,40,.08);border-color:#cfd1c8}.card-art{height:174px;border-radius:12px 12px 0 0;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;text-decoration:none;color:#fff}.card-art>span{font-family:'Newsreader',serif;font-size:52px;z-index:2;letter-spacing:-3px}.card-art .external{position:absolute;right:13px;top:13px;opacity:0;transition:.2s;z-index:3}.card-art:hover .external{opacity:1}.art-grain{position:absolute;inset:0;opacity:.25;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}.art-ai{background:radial-gradient(circle at 70% 30%,#ff795f 0 9%,transparent 10%),linear-gradient(135deg,#172b28,#497464)}.art-linear{background:repeating-linear-gradient(135deg,transparent 0 14px,#ffffff14 15px 16px),linear-gradient(135deg,#6f5aa7,#a588d7)}.art-swiss{background:linear-gradient(90deg,#ef492f 0 34%,#f3e6cd 34% 67%,#203969 67%);color:#131313}.art-creative{background:radial-gradient(circle at 50% 50%,transparent 0 24%,#dfd7c7 25% 26%,transparent 27% 40%,#dfd7c7 41% 42%,transparent 43%),#30352f}.art-momentum{background:linear-gradient(150deg,#ccddec,#98b2c6);color:#263d52}.art-stripe{background:radial-gradient(circle at 20% 80%,#ffc190 0 15%,transparent 16%),radial-gradient(circle at 80% 25%,#9d83ef 0 20%,transparent 21%),#5143c2}.art-software{background:linear-gradient(135deg,#243e38 50%,#cbdcbd 50%);color:#fff}.art-work{background:linear-gradient(30deg,#f2c08c,#d97d6d);color:#5c271e}.card-body{padding:16px 17px 14px}.card-meta{display:flex;align-items:center;gap:6px;color:#868b85;font-size:10.5px}.favicon{width:17px;height:17px;border:1px solid #d9dbd4;background:white;border-radius:4px;display:grid;place-items:center;color:#3e4840;font-size:9px;font-weight:600}.dot{color:#c0c3bd}.card-title-row{display:flex;align-items:flex-start;gap:10px;margin-top:13px}.card-title-row>a{text-decoration:none;color:inherit;flex:1}.card-title-row h2{font-family:'Newsreader',serif;font-weight:600;font-size:19px;line-height:1.18;letter-spacing:-.25px;margin:0}.fav{border:0;background:none;color:#b5b8b1;padding:1px;cursor:pointer}.fav:hover,.fav.active{color:#b26b3f}.card-body>p{font-size:11.5px;line-height:1.5;color:#747a73;margin:9px 0 18px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.card-footer{border-top:1px solid #e3e4dd;padding-top:12px;display:flex;align-items:center;justify-content:space-between}.tags{display:flex;gap:5px;overflow:hidden}.tags span{font-size:8.5px;letter-spacing:.7px;color:#697168;background:#edefe8;border-radius:4px;padding:4px 6px;white-space:nowrap}.more{border:0;background:none;color:#9da19a;padding:2px;cursor:pointer}.more-wrap{position:relative}.context-menu{position:absolute;right:0;bottom:27px;width:115px;background:white;border:1px solid #dddcd4;box-shadow:0 10px 25px #2631261f;border-radius:8px;padding:5px;z-index:5}.context-menu button{width:100%;border:0;background:none;padding:7px 8px;display:flex;gap:8px;font-size:11px;border-radius:5px;cursor:pointer}.context-menu button:hover{background:#f2f3ee}.context-menu .danger{color:#a84b3e}.bookmarks.list